def build_table():
    vals = list(map(int, _DATA.split()))
    table = {}
    for i in range(0, len(vals), 8):
        v2, v3 = vals[i], vals[i + 1]
        table[(v2, v3)] = tuple(vals[i + 2:i + 8])
    return table

def main():
    V1, V2, V3 = map(int, sys.stdin.read().split())
    S = 7
    total = 3 * S ** 3
    # exactly-one volume is forced by the other two: V1 + 2*V2 + 3*V3 = total
    if V1 + 2 * V2 + 3 * V3 != total:
        print("No")
        return
    table = build_table()
    w = table.get((V2, V3))
    if w is None:
        print("No")
        return
    x2, y2, z2, x3, y3, z3 = w
    print("Yes")
    print(0, 0, 0, x2, y2, z2, x3, y3, z3)

if __name__ == "__main__":
    main()
